import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.Cz0TtJv6.js";const u=JSON.parse('{"title":"FAQ","description":"Honest answers — can you lose money (yes), why paper first, one-sided SOL, restarts, RPC, and the one-instance rule.","frontmatter":{"title":"FAQ","description":"Honest answers — can you lose money (yes), why paper first, one-sided SOL, restarts, RPC, and the one-instance rule."},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1786716878000}'),r={name:"faq.md"};function n(i,e,l,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>Straight answers. Where a question touches money, the honest answer comes first.</p><h2 id="can-i-lose-money" tabindex="-1">Can I lose money? <a class="header-anchor" href="#can-i-lose-money" aria-label="Permalink to &quot;Can I lose money?&quot;">​</a></h2><p><strong>Yes.</strong> From the project&#39;s own disclaimers, verbatim:</p><blockquote><p>Memecoin LP can wipe a wallet. Not financial advice. Burner only.</p></blockquote><blockquote><p>Provided as-is. You can lose 100% of funds under this bot&#39;s control. Paper first. Burner only.</p></blockquote><p>The strategy&#39;s expectancy comes from many small fee wins plus <strong>rare full losses</strong> on rugs that beat the safety triggers. The vetting engine cannot catch a well-executed slow rug; sizing caps and brakes bound the damage, they don&#39;t eliminate it. The stop loss realizes −25%+ by definition when it fires. Use a dedicated burner wallet and assume its contents can go to zero. See <a href="./risk">Risk &amp; sizing</a>.</p><h2 id="why-paper-mode-first" tabindex="-1">Why paper mode first? <a class="header-anchor" href="#why-paper-mode-first" aria-label="Permalink to &quot;Why paper mode first?&quot;">​</a></h2><p>Three reasons:</p><ol><li><strong>The pipeline is identical.</strong> Paper runs the full brain — real scanning, real vetting, real pool data — with simulated fills. What you learn transfers.</li><li><strong>The promotion gate needs data.</strong> <code>npm run status</code> tracks consecutive profitable paper days; eligibility is <strong>7 in a row</strong> (after simulated costs). That scoreboard is how you decide with evidence instead of hope.</li><li><strong>Live is double-locked on purpose.</strong> Real trading requires <strong>both</strong> <code>[exec] mode = &quot;live&quot;</code> in config <strong>and</strong> <code>FARMER_MODE=live</code> in the environment. One switch alone stays safe — no single mis-click starts spending SOL.</li></ol><h2 id="what-s-the-usage-fee" tabindex="-1">What&#39;s the usage fee? <a class="header-anchor" href="#what-s-the-usage-fee" aria-label="Permalink to &quot;What&#39;s the usage fee?&quot;">​</a></h2><p>See <strong><a href="./fees">Fees</a></strong> — 1% GNME buy-and-burn on live winning closes only.</p><h2 id="why-one-sided-sol-below-price" tabindex="-1">Why one-sided SOL below price? <a class="header-anchor" href="#why-one-sided-sol-below-price" aria-label="Permalink to &quot;Why one-sided SOL below price?&quot;">​</a></h2><p>Because it&#39;s the shape where &quot;nothing happens&quot; costs you almost nothing:</p><ul><li>Price <strong>dips into the range</strong> → the bins buy tokens progressively cheaper; if price recovers back through, the same bins sell them above acquisition price, plus fees both ways. That&#39;s the win condition.</li><li>Price <strong>never visits</strong> → your SOL was never converted. No loss — just idle capital and a little rent.</li><li>Price <strong>falls through the bottom</strong> → you hold tokens bought on the way down; the mechanical P5/P1/P0 exits cut it rather than riding to zero.</li></ul><p>Compare a two-sided or above-price entry: you&#39;d hold the token from minute one, exposed to the full downside before earning anything. One-sided-below is the capital-preservation-first version of LPing memes. See <a href="./how-it-works">How it works</a>.</p><h2 id="what-happens-when-the-bot-restarts" tabindex="-1">What happens when the bot restarts? <a class="header-anchor" href="#what-happens-when-the-bot-restarts" aria-label="Permalink to &quot;What happens when the bot restarts?&quot;">​</a></h2><p>Restarts are safe by design:</p><ul><li>Positions live in SQLite, not memory.</li><li>On startup, the bot enumerates the wallet&#39;s actual on-chain DLMM positions and reconciles: <strong>the chain wins</strong>, the DB gets repaired, discrepancies are logged.</li><li>Paper mode simply resumes its simulated positions.</li><li>Amounts are always taken from parsed transaction results, never from what the bot <em>intended</em> to do.</li></ul><p>Crash-restart loops are handled by PM2/Railway supervision; the out-of-process heartbeat checker tells you if the farmer is actually gone (an in-process alert can&#39;t report its own death).</p><h2 id="what-are-the-rpc-requirements" tabindex="-1">What are the RPC requirements? <a class="header-anchor" href="#what-are-the-rpc-requirements" aria-label="Permalink to &quot;What are the RPC requirements?&quot;">​</a></h2><ul><li><strong>Paper:</strong> still use a real RPC — we suggest <a href="https://www.helius.dev/" target="_blank" rel="noreferrer">Helius</a> (<code>RPC_URL</code>). Public mainnet works for a smoke test but chokes under load.</li><li><strong>Live:</strong> Helius (or another private RPC) is strongly recommended. The manager polls every open position on a 15s cadence plus holder snapshots, claims, and swaps — free public endpoints rate-limit exactly when it matters.</li><li><strong>Jupiter:</strong> get a free API key at <a href="https://developers.jup.ag/portal" target="_blank" rel="noreferrer">developers.jup.ag/portal</a> (<code>JUPITER_API_KEY</code>). Required for the live swap path and for <code>npm run simulate-zap</code> before you trust live mode. Copy the key at creation — Jupiter shows it only once. <a href="https://developers.jup.ag/docs/portal/setup" target="_blank" rel="noreferrer">Setup guide</a>.</li><li>If RPC goes dark, the bot <strong>freezes new entries and alerts</strong> — it never blind-closes positions it can&#39;t see. See <a href="./risk#watchdog-liveness">Risk &amp; sizing → Watchdog</a>.</li></ul><h2 id="why-one-bot-instance-per-wallet" tabindex="-1">Why one bot instance per wallet? <a class="header-anchor" href="#why-one-bot-instance-per-wallet" aria-label="Permalink to &quot;Why one bot instance per wallet?&quot;">​</a></h2><p>Two loops against the same wallet/DB would double-trade the same strategy — same entries, conflicting exits, corrupted accounting. The loop holds <code>data/farmer.lock</code>, but the lock is <strong>per-machine</strong>: it cannot stop a dev PC and a server both running. When one host takes over, stop the other.</p><h2 id="the-windows-kill-gotcha" tabindex="-1">The Windows kill gotcha <a class="header-anchor" href="#the-windows-kill-gotcha" aria-label="Permalink to &quot;The Windows kill gotcha&quot;">​</a></h2><p>On Windows, killing a background <code>npm run run</code> kills <strong>only the npm wrapper</strong> — the <code>tsx</code> child process survives and keeps trading. To actually stop it: kill every node process whose command line matches the repo path, then delete <code>data/farmer.lock</code>. (Or avoid the situation: use <code>npm run pause</code> / <code>npm run halt</code> to stop trading before touching processes.)</p><h2 id="do-i-need-the-gmgn-api-key" tabindex="-1">Do I need the GMGN API key? <a class="header-anchor" href="#do-i-need-the-gmgn-api-key" aria-label="Permalink to &quot;Do I need the GMGN API key?&quot;">​</a></h2><p>No — the core pipeline runs without it. With a key you get trending/smart-money score bonuses (capped at +10) and extra honeypot/sell-tax vetting.</p><p><strong>How to get one (free):</strong> <a href="./api-keys#gmgn-api-key-gmgn_api_key-optional">API keys → GMGN</a> — generate an Ed25519 public key, upload at <a href="https://gmgn.ai/ai" target="_blank" rel="noreferrer">gmgn.ai/ai</a>, paste the API key as <code>GMGN_API_KEY</code>. You do <strong>not</strong> need <code>GMGN_PRIVATE_KEY</code> for this bot.</p><h2 id="can-the-bot-trade-sol-usdc-or-other-stable-pairs" tabindex="-1">Can the bot trade SOL-USDC or other stable pairs? <a class="header-anchor" href="#can-the-bot-trade-sol-usdc-or-other-stable-pairs" aria-label="Permalink to &quot;Can the bot trade SOL-USDC or other stable pairs?&quot;">​</a></h2><p>No, and it&#39;s not planned — stable pairs are <strong>permanently out of scope</strong>, a decided non-feature. The strategy is SOL-quoted only: the accumulate-SOL thesis, with PnL measured in SOL.</p><h2 id="where-do-my-settings-actually-live" tabindex="-1">Where do my settings actually live? <a class="header-anchor" href="#where-do-my-settings-actually-live" aria-label="Permalink to &quot;Where do my settings actually live?&quot;">​</a></h2><p>Under <code>data/</code> on your host or Railway volume (<code>data/config.toml</code>, <code>data/.env</code>, <code>data/farmer.db</code>). The repo&#39;s <code>config.toml</code> is only a first-run template. Config changes <strong>hot-reload</strong> — no restart needed. See <a href="./configuration">Configuration reference</a>.</p><h2 id="is-this-custody-who-holds-my-keys" tabindex="-1">Is this custody? Who holds my keys? <a class="header-anchor" href="#is-this-custody-who-holds-my-keys" aria-label="Permalink to &quot;Is this custody? Who holds my keys?&quot;">​</a></h2><p>You do. The encrypted wallet (<code>wallet.enc.json</code>) lives on <strong>your</strong> volume/host, encrypted with <strong>your</strong> passphrase. Nothing is sent to the project&#39;s servers. It is not a hosted trading service.</p><h2 id="is-this-open-source-can-i-copy-it" tabindex="-1">Is this open source? Can I copy it? <a class="header-anchor" href="#is-this-open-source-can-i-copy-it" aria-label="Permalink to &quot;Is this open source? Can I copy it?&quot;">​</a></h2><p>The code is public to <strong>run, study, and modify for your own bot</strong>. The license is <strong><a href="https://github.com/CryptoGnome/dlmmbot/blob/main/LICENSE" target="_blank" rel="noreferrer">PolyForm Shield 1.0.0</a></strong> — you cannot ship a competing product or hosted copy. Full terms are in the repo <code>LICENSE</code>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./risk">Risk &amp; sizing</a> — the full safety model</li><li><a href="./how-it-works">How it works</a> — the pipeline in plain language</li><li><a href="./strategy">Strategy reference</a> — every exit rule</li><li><a href="./easy">Easy setup (Railway)</a> · <a href="./advanced">Advanced setup</a></li><li><a href="./cli">CLI reference</a> — status, halt, pause, force-close</li></ul>',39)])])}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
